-- legacy:0020_stage4_review_hardening:begin
-- Preserve the configured overlap policy on each admitted run so PostgreSQL
-- can enforce the invariant without an unsafe cross-table partial predicate.
ALTER TABLE automation_runs
  ADD COLUMN enforce_no_overlap boolean NOT NULL DEFAULT false;
UPDATE automation_runs run
SET enforce_no_overlap=loop.no_overlap
FROM loops loop
WHERE run.loop_id=loop.id;
DROP INDEX loops_no_active_overlap;
CREATE UNIQUE INDEX loops_one_active_run_when_enforced
  ON automation_runs(loop_id)
  WHERE loop_id IS NOT NULL
    AND enforce_no_overlap
    AND status IN ('pending','claimed','running');

-- An external effect is durably moved to "prepared" before network I/O. If a
-- worker crashes after the receiver accepted the request, reconciliation marks
-- the unknown outcome without repeating a side effect that has no supported
-- idempotency contract.
CREATE TYPE automation_external_intent_state AS ENUM
  ('prepared','acknowledged','uncertain');
CREATE TABLE automation_external_effect_intents (
  effect_id uuid PRIMARY KEY REFERENCES automation_effects(id) ON DELETE RESTRICT,
  effect_key text NOT NULL UNIQUE,
  request_hash text NOT NULL,
  state automation_external_intent_state NOT NULL DEFAULT 'prepared',
  response_status integer,
  response_receipt text,
  prepared_at timestamptz NOT NULL DEFAULT now(),
  acknowledged_at timestamptz,
  reconciled_at timestamptz,
  CHECK((state='acknowledged')=(acknowledged_at IS NOT NULL)),
  CHECK(state<>'uncertain' OR reconciled_at IS NOT NULL)
);

-- A2A deliveries are monotonic per binding/task and can be consumed as a
-- durable WorkMesh-events-to-A2A stream.
ALTER TABLE a2a_deliveries
  ADD COLUMN sequence bigint,
  ADD COLUMN session_id uuid REFERENCES agent_sessions(id) ON DELETE RESTRICT,
  ADD COLUMN domain_event_id uuid REFERENCES domain_events(id) ON DELETE RESTRICT;
CREATE UNIQUE INDEX a2a_delivery_task_sequence
  ON a2a_deliveries(binding_id,external_task_id,sequence)
  WHERE external_task_id IS NOT NULL AND sequence IS NOT NULL;
CREATE UNIQUE INDEX a2a_delivery_domain_event
  ON a2a_deliveries(binding_id,domain_event_id)
  WHERE domain_event_id IS NOT NULL;
CREATE INDEX a2a_delivery_claim
  ON a2a_deliveries(received_at)
  WHERE status='received' AND attempt_count<8;
-- legacy:0020_stage4_review_hardening:end

-- legacy:0021_stage4_a2a_direction_and_prompt_identity:begin
-- Inbound A2A delivery sequence and outbound Domain Event cursor are distinct
-- monotonic domains. Keeping the direction on each fact prevents equal numeric
-- values from colliding while preserving one durable delivery audit table.
ALTER TABLE a2a_deliveries
  ADD COLUMN direction text NOT NULL DEFAULT 'inbound'
    CHECK(direction IN ('inbound','outbound'));
UPDATE a2a_deliveries
SET direction='outbound'
WHERE domain_event_id IS NOT NULL;
DROP INDEX a2a_delivery_task_sequence;
CREATE UNIQUE INDEX a2a_delivery_task_direction_sequence
  ON a2a_deliveries(binding_id,external_task_id,direction,sequence)
  WHERE external_task_id IS NOT NULL AND sequence IS NOT NULL;

-- A2A status deliveries repeat prior history. Persist the external identity so
-- later deliveries add only new prompts to the immutable prompt timeline.
ALTER TABLE agent_session_prompts
  ADD COLUMN a2a_external_message_id text;
CREATE UNIQUE INDEX agent_session_prompts_a2a_external_message
  ON agent_session_prompts(session_id,a2a_external_message_id)
  WHERE a2a_external_message_id IS NOT NULL;
-- legacy:0021_stage4_a2a_direction_and_prompt_identity:end

-- legacy:0022_route_policy_authorization_denials:begin
-- Authorization denials are append-only security facts. They deliberately have
-- no foreign keys to principals/resources so later deletion cannot erase the
-- audit trail and so audit recording never discloses protected rows.
CREATE TABLE authorization_denials (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  occurred_at timestamptz NOT NULL DEFAULT now(),
  correlation_id text NOT NULL,
  policy_id text NOT NULL,
  operation_id text NOT NULL,
  transport text NOT NULL CHECK(transport IN ('rest','sse','mcp','sdk')),
  principal_kind actor_kind,
  principal_actor_id uuid,
  principal_session_id uuid,
  workspace_id uuid,
  route_template text NOT NULL,
  reason_code text NOT NULL,
  authorization_stage text NOT NULL CHECK(authorization_stage IN (
    'identity','session','delegation','capability','resource_scope',
    'human_role','approval','lease','revision','idempotency','handler'
  )),
  resource_fingerprint text,
  dedupe_key text,
  CHECK(resource_fingerprint IS NULL OR resource_fingerprint ~ '^[0-9a-f]{64}$'),
  CHECK(dedupe_key IS NULL OR dedupe_key ~ '^[0-9a-f]{64}$')
);
CREATE INDEX authorization_denials_workspace_time
  ON authorization_denials(workspace_id,occurred_at DESC);
CREATE INDEX authorization_denials_correlation
  ON authorization_denials(correlation_id);
CREATE INDEX authorization_denials_policy_reason
  ON authorization_denials(policy_id,reason_code,occurred_at DESC);
CREATE UNIQUE INDEX authorization_denials_dedupe
  ON authorization_denials(dedupe_key)
  WHERE dedupe_key IS NOT NULL;
CREATE FUNCTION prevent_authorization_denial_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'IMMUTABLE_AUTHORIZATION_DENIAL'; END
$$;
CREATE TRIGGER authorization_denials_immutable
  BEFORE UPDATE OR DELETE ON authorization_denials
  FOR EACH ROW EXECUTE FUNCTION prevent_authorization_denial_mutation();

-- Stage 4 originally had only Workspace-wide Templates. A nullable Team scope
-- is additive: existing rows remain Workspace-admin-only while new Team rows
-- can be exposed to explicit members without broad Workspace enumeration.
ALTER TABLE templates ADD COLUMN team_id uuid;
ALTER TABLE templates
  ADD CONSTRAINT templates_workspace_team_fk
  FOREIGN KEY(workspace_id,team_id)
  REFERENCES teams(workspace_id,id)
  ON DELETE RESTRICT;
CREATE INDEX templates_workspace_team_status
  ON templates(workspace_id,team_id,status);
-- legacy:0022_route_policy_authorization_denials:end

-- legacy:0023_auth_idempotency_records:begin
ALTER TABLE sessions ADD COLUMN revoked_at timestamptz;
CREATE INDEX sessions_token_active
  ON sessions(token_hash)
  WHERE revoked_at IS NULL;

CREATE TABLE auth_idempotency_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key_fingerprint text NOT NULL,
  subject_fingerprint text NOT NULL,
  operation text NOT NULL,
  request_fingerprint text NOT NULL,
  client_context_fingerprint text NOT NULL,
  state text NOT NULL DEFAULT 'claimed' CHECK(state IN ('claimed','completed')),
  response_status integer,
  replay_key_id text,
  replay_key_fingerprint text,
  replay_iv bytea,
  replay_tag bytea,
  replay_ciphertext bytea,
  replay_expires_at timestamptz NOT NULL DEFAULT now() + interval '15 minutes',
  conflict_expires_at timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  created_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  replay_wiped_at timestamptz,
  UNIQUE(key_fingerprint,subject_fingerprint),
  CHECK(key_fingerprint ~ '^[0-9a-f]{64}$'),
  CHECK(subject_fingerprint ~ '^[0-9a-f]{64}$'),
  CHECK(request_fingerprint ~ '^[0-9a-f]{64}$'),
  CHECK(client_context_fingerprint ~ '^[0-9a-f]{64}$'),
  CHECK(replay_key_fingerprint IS NULL OR replay_key_fingerprint ~ '^[0-9a-f]{64}$'),
  CHECK(
    (state='claimed' AND response_status IS NULL AND replay_key_id IS NULL
      AND replay_key_fingerprint IS NULL AND replay_iv IS NULL
      AND replay_tag IS NULL AND replay_ciphertext IS NULL AND completed_at IS NULL
      AND replay_wiped_at IS NULL)
    OR
    (state='completed' AND response_status IS NOT NULL AND replay_key_id IS NOT NULL
      AND replay_key_fingerprint IS NOT NULL AND replay_iv IS NOT NULL
      AND replay_tag IS NOT NULL AND replay_ciphertext IS NOT NULL
      AND completed_at IS NOT NULL AND replay_wiped_at IS NULL)
    OR
    (state='completed' AND response_status IS NULL AND replay_key_id IS NULL
      AND replay_key_fingerprint IS NULL AND replay_iv IS NULL
      AND replay_tag IS NULL AND replay_ciphertext IS NULL
      AND completed_at IS NOT NULL AND replay_wiped_at IS NOT NULL)
  )
);

CREATE INDEX auth_idempotency_records_replay_expiry
  ON auth_idempotency_records(replay_expires_at,id)
  WHERE state='completed' AND replay_wiped_at IS NULL;
CREATE INDEX auth_idempotency_records_conflict_expiry
  ON auth_idempotency_records(conflict_expires_at,id);
-- legacy:0023_auth_idempotency_records:end

