-- legacy:0029_exact_archive_membership:begin
-- Segment cursor bounds are an object envelope, not proof that every cursor
-- between them is present. Existing segments must be indexed from their pinned
-- immutable object before they can authorize coverage, cleanup, or pruning.
CREATE TYPE event_archive_membership_state AS ENUM (
  'pending_exact',
  'exact',
  'legacy_unindexed'
);

ALTER TABLE event_archive_segments
  ADD COLUMN membership_state event_archive_membership_state
    NOT NULL DEFAULT 'legacy_unindexed';

ALTER TABLE event_archive_segments
  ALTER COLUMN membership_state SET DEFAULT 'pending_exact';

ALTER TABLE event_archive_segments
  DROP CONSTRAINT IF EXISTS
    event_archive_segments_workspace_id_start_cursor_end_cursor_key;

ALTER TABLE event_archive_segments
  ADD CONSTRAINT event_archive_segments_id_workspace_unique
    UNIQUE(id,workspace_id),
  ADD CONSTRAINT event_archive_segments_membership_state_check CHECK (
    membership_state <> 'exact'
    OR state IN ('verified','pruned')
  );

CREATE TABLE event_archive_segment_events (
  segment_id uuid NOT NULL,
  workspace_id uuid NOT NULL,
  ordinal integer NOT NULL CHECK(ordinal >= 0),
  event_id uuid NOT NULL,
  event_cursor bigint NOT NULL CHECK(event_cursor > 0),
  record_sha256 text NOT NULL
    CHECK(record_sha256 ~ '^sha256:[a-f0-9]{64}$'),
  floored_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(segment_id,ordinal),
  UNIQUE(workspace_id,event_id),
  UNIQUE(workspace_id,event_cursor),
  FOREIGN KEY(segment_id,workspace_id)
    REFERENCES event_archive_segments(id,workspace_id)
    ON DELETE RESTRICT
);

CREATE INDEX event_archive_segment_events_segment_floor
  ON event_archive_segment_events(segment_id,floored_at,ordinal);
CREATE INDEX event_archive_segment_events_workspace_floor
  ON event_archive_segment_events(workspace_id,event_cursor,floored_at);

COMMENT ON COLUMN event_archive_segments.start_cursor IS
  'Minimum event cursor in the immutable object; envelope only, never coverage.';
COMMENT ON COLUMN event_archive_segments.end_cursor IS
  'Maximum event cursor in the immutable object; envelope only, never coverage.';
COMMENT ON COLUMN event_archive_segments.membership_state IS
  'Only exact is authoritative; legacy_unindexed requires pinned-object materialization.';
COMMENT ON TABLE event_archive_segment_events IS
  'Exact immutable archive membership retained after online domain event deletion.';
-- legacy:0029_exact_archive_membership:end

-- legacy:0030_durable_archive_upload_intents:begin
-- This is a secondary database-side barrier after operators have stopped the
-- old Worker and run the exact target-image S3 reconciliation. It closes the
-- race with any residual retention writer for the whole migration.
LOCK TABLE retention_job_state IN SHARE ROW EXCLUSIVE MODE;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
      FROM retention_job_state
     WHERE job_name<>'worker_runtime'
       AND lease_owner IS NOT NULL
       AND lease_expires_at>now()
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE='55006',
      MESSAGE='UPGRADE_BARRIER_RETENTION_CLAIM_ACTIVE';
  END IF;
END;
$$;

-- Before this migration pending_exact meant only "membership has not been
-- materialized yet"; those rows predate durable upload intents and have no
-- provisional reservations. Preserve them on the pinned-object legacy path.
UPDATE event_archive_segments
   SET membership_state='legacy_unindexed',
       updated_at=now()
 WHERE membership_state='pending_exact';

ALTER TABLE event_archive_segments
  ALTER COLUMN object_version_id DROP NOT NULL,
  ADD COLUMN upload_attempt_count integer NOT NULL DEFAULT 0,
  ADD COLUMN last_upload_attempt_at timestamptz,
  ADD COLUMN last_upload_fence bigint,
  ADD COLUMN planned_fence bigint;

-- Canonical metadata did not originally require the frozen cutoff. PostgreSQL
-- timestamps may retain microseconds while the Node.js Date boundary is
-- millisecond-precise, so normalize historical values to that shared precision
-- and write the exact UTC ISO spelling produced by Date#toISOString().
UPDATE event_archive_segments
   SET fixed_cutoff_at=date_trunc('milliseconds',fixed_cutoff_at),
       metadata=jsonb_set(
         metadata,
         '{fixedCutoffAt}',
         to_jsonb(
           to_char(
             date_trunc('milliseconds',fixed_cutoff_at) AT TIME ZONE 'UTC',
             'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
           )
         ),
         true
       );

-- Replace the original state/timestamp checks and the 0029 membership check
-- with one explicit durable-intent state machine. Constraint names generated
-- for the old anonymous CHECKs differ between PostgreSQL versions, so identify
-- only checks that reference the replaced columns.
DO $$
DECLARE
  constraint_row record;
BEGIN
  FOR constraint_row IN
    SELECT conname
      FROM pg_constraint
     WHERE conrelid='event_archive_segments'::regclass
       AND contype='c'
       AND (
         pg_get_constraintdef(oid) ILIKE '%object_version_id%'
         OR pg_get_constraintdef(oid) ILIKE '%uploaded_at%'
         OR pg_get_constraintdef(oid) ILIKE '%verified_at%'
         OR pg_get_constraintdef(oid) ILIKE '%pruned_at%'
         OR pg_get_constraintdef(oid) ILIKE '%membership_state%'
       )
  LOOP
    EXECUTE format(
      'ALTER TABLE event_archive_segments DROP CONSTRAINT %I',
      constraint_row.conname
    );
  END LOOP;
END;
$$;

-- The pre-intent worker represented a failed readback by clearing uploaded_at
-- even though the immutable VersionId was already durable. After removing the
-- old state/timestamp checks, preserve that recoverable object on the legacy
-- path while satisfying the explicit pairing installed below.
UPDATE event_archive_segments
   SET uploaded_at=COALESCE(uploaded_at,created_at),
       updated_at=now()
 WHERE membership_state='legacy_unindexed'
   AND state='failed'
   AND object_version_id IS NOT NULL
   AND uploaded_at IS NULL;

ALTER TABLE event_archive_segments
  ADD CONSTRAINT event_archive_segments_object_version_state_check CHECK (
    (
      state='planned'
      AND object_version_id IS NULL
    )
    OR (
      state IN ('uploaded','verified','pruned')
      AND object_version_id IS NOT NULL
      AND length(btrim(object_version_id)) BETWEEN 1 AND 1024
    )
    OR (
      state='failed'
      AND (
        object_version_id IS NULL
        OR (
          object_version_id IS NOT NULL
          AND length(btrim(object_version_id)) BETWEEN 1 AND 1024
        )
      )
    )
  ),
  ADD CONSTRAINT event_archive_segments_timestamp_state_check CHECK (
    (state='planned'
      AND uploaded_at IS NULL AND verified_at IS NULL AND pruned_at IS NULL)
    OR
    (state='uploaded'
      AND uploaded_at IS NOT NULL AND verified_at IS NULL AND pruned_at IS NULL)
    OR
    (state='verified'
      AND uploaded_at IS NOT NULL AND verified_at IS NOT NULL
      AND pruned_at IS NULL)
    OR
    (state='pruned'
      AND uploaded_at IS NOT NULL AND verified_at IS NOT NULL
      AND pruned_at IS NOT NULL)
    OR
    (state='failed'
      AND verified_at IS NULL AND pruned_at IS NULL
      AND (
        (object_version_id IS NULL AND uploaded_at IS NULL)
        OR (object_version_id IS NOT NULL AND uploaded_at IS NOT NULL)
      ))
  ),
  ADD CONSTRAINT event_archive_segments_membership_state_check CHECK (
    (
      membership_state='pending_exact'
      AND state IN ('planned','uploaded','failed')
      AND planned_fence IS NOT NULL
      AND planned_fence >= 0
      AND (
        state <> 'failed'
        OR last_error_code IN (
          'RETENTION_OBJECT_IDENTITY_MISMATCH',
          'ARCHIVE_FIXED_CUTOFF_MISMATCH',
          'ARCHIVE_PLAN_CONFLICT',
          'ARCHIVE_MEMBERSHIP_CONFLICT',
          'ARCHIVE_OBJECT_MANIFEST_MISMATCH',
          'ARCHIVE_SNAPSHOT_RECHECK_FAILED'
        )
      )
    )
    OR (
      membership_state='exact'
      AND state IN ('verified','pruned')
      AND object_version_id IS NOT NULL
    )
    OR (
      membership_state='legacy_unindexed'
      AND state IN ('uploaded','verified','pruned','failed')
      AND object_version_id IS NOT NULL
    )
  ),
  ADD CONSTRAINT event_archive_segments_upload_attempt_check CHECK (
    upload_attempt_count >= 0
    AND (
      (
        upload_attempt_count=0
        AND last_upload_attempt_at IS NULL
        AND last_upload_fence IS NULL
      )
      OR (
        upload_attempt_count>0
        AND last_upload_attempt_at IS NOT NULL
        AND last_upload_fence IS NOT NULL
        AND last_upload_fence >= 0
      )
    )
  ),
  ADD CONSTRAINT event_archive_segments_fixed_cutoff_metadata_check CHECK (
    jsonb_typeof(metadata->'fixedCutoffAt')='string'
    AND metadata->>'fixedCutoffAt'=to_char(
      fixed_cutoff_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    )
    AND (metadata->>'fixedCutoffAt')::timestamptz=fixed_cutoff_at
  );

-- At most one durable intent can exist for a Workspace. A deterministic
-- conflict stays visible and blocks a replacement until an operator resolves
-- it; retries always recover the same stable object key.
CREATE UNIQUE INDEX event_archive_segments_one_pending_intent
  ON event_archive_segments(workspace_id)
  WHERE membership_state='pending_exact';

CREATE INDEX event_archive_segments_pending_recovery
  ON event_archive_segments(workspace_id,created_at,id)
  WHERE membership_state='pending_exact'
    AND state IN ('planned','uploaded','failed');

COMMENT ON COLUMN event_archive_segments.planned_fence IS
  'Fence that created the durable intent; successors may reconcile it.';
COMMENT ON COLUMN event_archive_segments.last_upload_fence IS
  'Fence that most recently attempted the stable-key conditional upload.';
COMMENT ON COLUMN event_archive_segments.upload_attempt_count IS
  'Durable count of same-key conditional upload/reconcile attempts.';
COMMENT ON INDEX event_archive_segments_one_pending_intent IS
  'Prevents a second immutable upload intent while recovery is pending.';
-- legacy:0030_durable_archive_upload_intents:end

-- legacy:0031_agent_session_external_urls_shape:begin
ALTER TABLE agent_sessions
  ADD CONSTRAINT agent_sessions_external_urls_array_check
  CHECK (jsonb_typeof(external_urls) = 'array') NOT VALID;

ALTER TABLE api_idempotency_keys
  ADD CONSTRAINT api_idempotency_ack_session_external_urls_array_check
  CHECK (
    operation <> 'acknowledgeAgentSession'
    OR response_body IS NULL
    OR COALESCE(
      jsonb_typeof(response_body) = 'object'
      AND jsonb_typeof(response_body->'external_urls') = 'array',
      false
    )
  ) NOT VALID;

UPDATE agent_sessions
  SET external_urls = '[]'::jsonb
  WHERE external_urls = '{}'::jsonb;

UPDATE api_idempotency_keys
  SET response_body = jsonb_set(
    response_body,
    '{external_urls}',
    '[]'::jsonb,
    false
  )
  WHERE operation = 'acknowledgeAgentSession'
    AND response_body->'external_urls' = '{}'::jsonb;

ALTER TABLE agent_sessions
  VALIDATE CONSTRAINT agent_sessions_external_urls_array_check;

ALTER TABLE api_idempotency_keys
  VALIDATE CONSTRAINT api_idempotency_ack_session_external_urls_array_check;
-- legacy:0031_agent_session_external_urls_shape:end

-- legacy:0032_agent_inbox_receipts:begin
ALTER TYPE inbox_item_kind ADD VALUE IF NOT EXISTS 'mention';


CREATE TYPE inbox_receipt_kind AS ENUM ('claimed','read','acknowledged','replied');

ALTER TABLE agent_sessions
  ADD CONSTRAINT agent_sessions_workspace_id_id_actor_key
  UNIQUE(workspace_id,id,agent_actor_id);
ALTER TABLE room_messages
  ADD CONSTRAINT room_messages_workspace_id_id_key UNIQUE(workspace_id,id);
ALTER TABLE inbox_items
  ADD CONSTRAINT inbox_items_workspace_id_id_key UNIQUE(workspace_id,id);

ALTER TABLE inbox_items
  ALTER COLUMN recipient_human_actor_id DROP NOT NULL,
  ADD COLUMN recipient_actor_id uuid,
  ADD COLUMN recipient_session_id uuid,
  ADD COLUMN claimed_by_session_id uuid,
  ADD COLUMN claimed_at timestamptz,
  ADD COLUMN team_id uuid,
  ADD COLUMN source_room_message_id uuid,
  ADD COLUMN requires_response boolean NOT NULL DEFAULT false,
  ADD COLUMN revision integer NOT NULL DEFAULT 1 CHECK(revision > 0);

-- Keep pre-0032 writers valid during a rolling deploy.  Those writers know
-- only recipient_human_actor_id; the compatibility trigger mirrors that
-- durable Human recipient into the new unified actor column before constraints
-- are checked.  Agent recipients continue to write recipient_actor_id directly.
CREATE FUNCTION sync_legacy_inbox_recipient() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.recipient_human_actor_id IS NOT NULL THEN
    NEW.recipient_actor_id := NEW.recipient_human_actor_id;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER inbox_items_00_sync_legacy_recipient
  BEFORE INSERT OR UPDATE OF recipient_human_actor_id,recipient_actor_id
  ON inbox_items FOR EACH ROW EXECUTE FUNCTION sync_legacy_inbox_recipient();

UPDATE inbox_items
   SET recipient_actor_id=recipient_human_actor_id,
       source_room_message_id=CASE WHEN source_type='room_message' THEN source_id END
 WHERE recipient_actor_id IS NULL;

UPDATE inbox_items i
   SET team_id=s.team_id
  FROM agent_sessions s
 WHERE i.team_id IS NULL
   AND i.session_id=s.id
   AND i.workspace_id=s.workspace_id;

UPDATE inbox_items i
   SET team_id=c.team_id
  FROM room_messages m
  JOIN work_room_channels c
    ON c.id=m.channel_id
   AND c.workspace_id=m.workspace_id
 WHERE i.team_id IS NULL
   AND i.source_type='room_message'
   AND i.source_id=m.id
   AND i.workspace_id=m.workspace_id;

ALTER TABLE inbox_items
  ALTER COLUMN recipient_actor_id SET NOT NULL,
  ADD CONSTRAINT inbox_items_recipient_actor_fk
    FOREIGN KEY(workspace_id,recipient_actor_id)
    REFERENCES actors(workspace_id,id) ON DELETE RESTRICT,
  ADD CONSTRAINT inbox_items_recipient_session_fk
    FOREIGN KEY(workspace_id,recipient_session_id,recipient_actor_id)
    REFERENCES agent_sessions(workspace_id,id,agent_actor_id) ON DELETE RESTRICT,
  ADD CONSTRAINT inbox_items_claimed_session_fk
    FOREIGN KEY(workspace_id,claimed_by_session_id,recipient_actor_id)
    REFERENCES agent_sessions(workspace_id,id,agent_actor_id) ON DELETE RESTRICT,
  ADD CONSTRAINT inbox_items_team_fk
    FOREIGN KEY(workspace_id,team_id)
    REFERENCES teams(workspace_id,id) ON DELETE RESTRICT,
  ADD CONSTRAINT inbox_items_source_room_message_fk
    FOREIGN KEY(workspace_id,source_room_message_id)
    REFERENCES room_messages(workspace_id,id) ON DELETE RESTRICT,
  ADD CONSTRAINT inbox_items_claim_pair_check
    CHECK((claimed_by_session_id IS NULL)=(claimed_at IS NULL)),
  ADD CONSTRAINT inbox_items_exact_claim_check
    CHECK(recipient_session_id IS NULL OR claimed_by_session_id IS NULL OR recipient_session_id=claimed_by_session_id),
  ADD CONSTRAINT inbox_items_recipient_kind_shape_check
    CHECK(
      (recipient_human_actor_id IS NOT NULL AND recipient_human_actor_id=recipient_actor_id
        AND recipient_session_id IS NULL AND claimed_by_session_id IS NULL)
      OR recipient_human_actor_id IS NULL
    );

CREATE UNIQUE INDEX inbox_items_actor_target_unique
  ON inbox_items(workspace_id,recipient_actor_id,kind,source_type,source_id)
  WHERE recipient_human_actor_id IS NULL AND recipient_session_id IS NULL;
CREATE UNIQUE INDEX inbox_items_session_target_unique
  ON inbox_items(workspace_id,recipient_session_id,kind,source_type,source_id)
  WHERE recipient_session_id IS NOT NULL;
CREATE INDEX inbox_items_agent_exact_page
  ON inbox_items(workspace_id,recipient_session_id,status,created_at DESC,id DESC)
  WHERE recipient_session_id IS NOT NULL;
CREATE INDEX inbox_items_agent_actor_page
  ON inbox_items(workspace_id,recipient_actor_id,status,created_at DESC,id DESC)
  WHERE recipient_human_actor_id IS NULL;
CREATE INDEX inbox_items_agent_claimed_page
  ON inbox_items(workspace_id,claimed_by_session_id,status,created_at DESC,id DESC)
  WHERE claimed_by_session_id IS NOT NULL;

CREATE TABLE room_message_session_recipients (
  message_id uuid NOT NULL,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  session_id uuid NOT NULL,
  actor_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(message_id,session_id),
  FOREIGN KEY(workspace_id,message_id)
    REFERENCES room_messages(workspace_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(workspace_id,session_id,actor_id)
    REFERENCES agent_sessions(workspace_id,id,agent_actor_id) ON DELETE RESTRICT
);
CREATE INDEX room_message_session_recipients_session
  ON room_message_session_recipients(workspace_id,session_id,created_at DESC,message_id);

CREATE TABLE inbox_item_receipts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  inbox_item_id uuid NOT NULL,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  actor_id uuid NOT NULL,
  session_id uuid NOT NULL,
  kind inbox_receipt_kind NOT NULL,
  reply_message_id uuid,
  correlation_id text NOT NULL,
  idempotency_key text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(workspace_id,inbox_item_id)
    REFERENCES inbox_items(workspace_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(workspace_id,reply_message_id)
    REFERENCES room_messages(workspace_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(workspace_id,session_id,actor_id)
    REFERENCES agent_sessions(workspace_id,id,agent_actor_id) ON DELETE RESTRICT,
  CHECK((kind='replied')=(reply_message_id IS NOT NULL))
);
CREATE UNIQUE INDEX inbox_item_receipts_single_fact
  ON inbox_item_receipts(inbox_item_id,session_id,kind)
  WHERE kind IN ('claimed','read','acknowledged');
CREATE UNIQUE INDEX inbox_item_receipts_reply
  ON inbox_item_receipts(inbox_item_id,reply_message_id)
  WHERE kind='replied';
CREATE INDEX inbox_item_receipts_history
  ON inbox_item_receipts(inbox_item_id,created_at,id);

CREATE FUNCTION enforce_inbox_actor_recipient() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE recipient_kind actor_kind;
BEGIN
  SELECT kind INTO recipient_kind
    FROM actors
   WHERE id=NEW.recipient_actor_id AND workspace_id=NEW.workspace_id;
  IF recipient_kind IS NULL THEN
    RAISE EXCEPTION 'INBOX_RECIPIENT_NOT_FOUND';
  END IF;
  IF NEW.recipient_human_actor_id IS NOT NULL AND recipient_kind <> 'human' THEN
    RAISE EXCEPTION 'INBOX_HUMAN_RECIPIENT_REQUIRED';
  END IF;
  IF NEW.recipient_human_actor_id IS NULL AND recipient_kind <> 'agent' THEN
    RAISE EXCEPTION 'INBOX_AGENT_RECIPIENT_REQUIRED';
  END IF;
  IF recipient_kind='agent' AND NEW.team_id IS NULL THEN
    RAISE EXCEPTION 'INBOX_AGENT_TEAM_REQUIRED';
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS inbox_items_require_human_recipient ON inbox_items;
CREATE TRIGGER inbox_items_10_actor_recipient
  BEFORE INSERT OR UPDATE OF recipient_actor_id,recipient_human_actor_id,recipient_session_id,team_id
  ON inbox_items FOR EACH ROW EXECUTE FUNCTION enforce_inbox_actor_recipient();

CREATE FUNCTION prevent_inbox_claim_rebind() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.claimed_by_session_id IS NOT NULL
     AND (
       NEW.claimed_by_session_id IS DISTINCT FROM OLD.claimed_by_session_id
       OR NEW.claimed_at IS DISTINCT FROM OLD.claimed_at
     ) THEN
    RAISE EXCEPTION 'INBOX_CLAIM_IMMUTABLE';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER inbox_claim_immutable
  BEFORE UPDATE OF claimed_by_session_id,claimed_at
  ON inbox_items FOR EACH ROW EXECUTE FUNCTION prevent_inbox_claim_rebind();

CREATE FUNCTION enforce_inbox_receipt_scope() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM inbox_items item
     WHERE item.workspace_id=NEW.workspace_id
       AND item.id=NEW.inbox_item_id
       AND item.recipient_actor_id=NEW.actor_id
       AND (
         (
           item.recipient_session_id IS NOT NULL
           AND item.recipient_session_id=NEW.session_id
         )
         OR (
           item.recipient_session_id IS NULL
           AND item.claimed_by_session_id=NEW.session_id
         )
       )
       AND (
         NEW.kind<>'claimed'
         OR (
           item.recipient_session_id IS NULL
           AND item.claimed_by_session_id=NEW.session_id
         )
       )
  ) THEN
    RAISE EXCEPTION 'INBOX_RECEIPT_RECIPIENT_MISMATCH';
  END IF;
  IF NEW.kind='replied' AND NOT EXISTS (
    SELECT 1
      FROM inbox_items item
      JOIN room_messages source_message
        ON source_message.workspace_id=item.workspace_id
       AND source_message.id=item.source_room_message_id
      JOIN room_messages reply_message
        ON reply_message.workspace_id=item.workspace_id
       AND reply_message.id=NEW.reply_message_id
     WHERE item.workspace_id=NEW.workspace_id
       AND item.id=NEW.inbox_item_id
       AND reply_message.channel_id=source_message.channel_id
  ) THEN
    RAISE EXCEPTION 'INBOX_REPLY_MESSAGE_SCOPE_MISMATCH';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER inbox_receipt_scope
  BEFORE INSERT ON inbox_item_receipts
  FOR EACH ROW EXECUTE FUNCTION enforce_inbox_receipt_scope();

CREATE TRIGGER room_message_session_recipients_immutable
  BEFORE UPDATE OR DELETE ON room_message_session_recipients
  FOR EACH ROW EXECUTE FUNCTION prevent_stage2_fact_mutation();
CREATE TRIGGER inbox_item_receipts_immutable
  BEFORE UPDATE OR DELETE ON inbox_item_receipts
  FOR EACH ROW EXECUTE FUNCTION prevent_stage2_fact_mutation();
-- legacy:0032_agent_inbox_receipts:end

-- legacy:0033_inbox_receipt_reply_binding:begin
CREATE OR REPLACE FUNCTION enforce_inbox_receipt_scope()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM inbox_items item
     WHERE item.workspace_id=NEW.workspace_id
       AND item.id=NEW.inbox_item_id
       AND item.recipient_actor_id=NEW.actor_id
       AND (
         (
           item.recipient_session_id IS NOT NULL
           AND item.recipient_session_id=NEW.session_id
         )
         OR (
           item.recipient_session_id IS NULL
           AND item.claimed_by_session_id=NEW.session_id
         )
       )
       AND (
         NEW.kind<>'claimed'
         OR (
           item.recipient_session_id IS NULL
           AND item.claimed_by_session_id=NEW.session_id
         )
       )
  ) THEN
    RAISE EXCEPTION 'INBOX_RECEIPT_RECIPIENT_MISMATCH';
  END IF;
  IF NEW.kind='replied' AND NOT EXISTS (
    SELECT 1
      FROM inbox_items item
      JOIN room_messages source_message
        ON source_message.workspace_id=item.workspace_id
       AND source_message.id=item.source_room_message_id
      JOIN room_messages reply_message
        ON reply_message.workspace_id=item.workspace_id
       AND reply_message.id=NEW.reply_message_id
     WHERE item.workspace_id=NEW.workspace_id
       AND item.id=NEW.inbox_item_id
       AND reply_message.channel_id=source_message.channel_id
       AND reply_message.author_actor_id=NEW.actor_id
       AND reply_message.session_id=NEW.session_id
       AND reply_message.reply_to_message_id=source_message.id
  ) THEN
    RAISE EXCEPTION 'INBOX_REPLY_MESSAGE_SCOPE_MISMATCH';
  END IF;
  RETURN NEW;
END $$;
-- legacy:0033_inbox_receipt_reply_binding:end

-- legacy:0034_legacy_inbox_scope_derivation:begin
-- Rolling deployments may keep pre-0032 Human Inbox producers alive after
-- 0032 is applied. Derive the disclosure scope those producer shapes omit
-- without changing the applied 0032 or 0033 migrations.
CREATE OR REPLACE FUNCTION sync_legacy_inbox_recipient()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  derived_room_message_id uuid;
  derived_room_team_id uuid;
  derived_session_team_id uuid;
BEGIN
  IF NEW.recipient_human_actor_id IS NOT NULL THEN
    NEW.recipient_actor_id := NEW.recipient_human_actor_id;
  END IF;

  IF NEW.source_room_message_id IS NOT NULL THEN
    SELECT message.id,channel.team_id
      INTO derived_room_message_id,derived_room_team_id
      FROM room_messages message
      JOIN work_room_channels channel
        ON channel.id=message.channel_id
       AND channel.workspace_id=message.workspace_id
     WHERE message.workspace_id=NEW.workspace_id
       AND message.id=NEW.source_room_message_id;
  ELSIF NEW.source_type='room_message' THEN
    SELECT message.id,channel.team_id
      INTO derived_room_message_id,derived_room_team_id
      FROM room_messages message
      JOIN work_room_channels channel
        ON channel.id=message.channel_id
       AND channel.workspace_id=message.workspace_id
     WHERE message.workspace_id=NEW.workspace_id
       AND message.id=NEW.source_id;
    IF derived_room_message_id IS NOT NULL THEN
      NEW.source_room_message_id := derived_room_message_id;
    END IF;
  END IF;

  IF NEW.team_id IS NULL THEN
    NEW.team_id := derived_room_team_id;
  END IF;
  IF NEW.team_id IS NULL AND NEW.session_id IS NOT NULL THEN
    SELECT session.team_id
      INTO derived_session_team_id
      FROM agent_sessions session
     WHERE session.workspace_id=NEW.workspace_id
       AND session.id=NEW.session_id;
    NEW.team_id := derived_session_team_id;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER inbox_items_00_sync_legacy_recipient ON inbox_items;
CREATE TRIGGER inbox_items_00_sync_legacy_recipient
  BEFORE INSERT OR UPDATE OF
    recipient_human_actor_id,recipient_actor_id,session_id,team_id,
    source_type,source_id,source_room_message_id
  ON inbox_items FOR EACH ROW EXECUTE FUNCTION sync_legacy_inbox_recipient();

-- Prefer a room message's Team for room-message producers. The source message
-- is the disclosure-bearing fact and is deterministic even when the old
-- producer omitted session_id.
UPDATE inbox_items item
   SET source_room_message_id=message.id,
       team_id=COALESCE(item.team_id,channel.team_id)
  FROM room_messages message
  JOIN work_room_channels channel
    ON channel.id=message.channel_id
   AND channel.workspace_id=message.workspace_id
 WHERE item.workspace_id=message.workspace_id
   AND item.source_type='room_message'
   AND item.source_id=message.id
   AND (
     item.source_room_message_id IS NULL
     OR item.team_id IS NULL
   );

-- Non-room legacy producers carry their source Session. Use its persisted Team
-- only when no room-derived Team was available.
UPDATE inbox_items item
   SET team_id=session.team_id
  FROM agent_sessions session
 WHERE item.workspace_id=session.workspace_id
   AND item.session_id=session.id
   AND item.team_id IS NULL;
-- legacy:0034_legacy_inbox_scope_derivation:end

